  /// capability overrides in insertion order.
  String toYaml() {
    final buffer = StringBuffer('models:\n');
    if (slots.isNotEmpty) {
      buffer.write('  slots:\n');
      for (final slot in mediaModelSlotIds) {
        final override = slots[slot];
        if (override == null) continue;
