cat > test/cli/zz_it3_debug_test.dart <<'EOF'
import 'dart:async';
import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:flutter_agent_harness/src/cli/tui_repl.dart';
import 'package:test/test.dart';
import 'package:yaml/yaml.dart';
import 'agent_cli_test_support.dart';

class _FrameSink implements StreamConsumer<List<int>> {
  final _bytes = BytesBuilder(copy: false);
  void add(List<int> data) => _bytes.add(data);
  void addError(Object error, [StackTrace? st]) {}
  @override
  Future<void> addStream(Stream<List<int>> stream) async { await for (final c in stream) { add(c); } }
  @override
  Future<void> close() async {}
  String get text => utf8.decode(_bytes.toBytes(), allowMalformed: true);
  String get plain => text
      .replaceAll(RegExp('\x1B\\][^\x07]*\x07'), '')
      .replaceAll(RegExp('\x1B\\[[0-9;?]*[A-Za-z]'), '');
}

final class _ThrowingWriteEnv implements ExecutionEnv {
  _ThrowingWriteEnv(this._delegate);
  final MemoryExecutionEnv _delegate;
  String? throwOnPath;
  int writeAttempts = 0;
  final writes = <String>[];
  @override
  Future<Result<void, FileError>> writeFile(String path, String content) async {
    writeAttempts++;
    writes.add(path);
    if (path == throwOnPath) throw StateError('disk full (forced by the test)');
    return _delegate.writeFile(path, content);
  }
  @override String get cwd => _delegate.cwd;
  @override Future<Result<String, FileError>> absolutePath(String path) => _delegate.absolutePath(path);
  @override Future<Result<void, FileError>> appendFile(String path, String content) => _delegate.appendFile(path, content);
  @override Future<Result<void, FileError>> createDir(String path, {bool recursive = true}) => _delegate.createDir(path, recursive: recursive);
  @override Future<Result<bool, FileError>> exists(String path) => _delegate.exists(path);
  @override Future<Result<FileInfo, FileError>> fileInfo(String path) => _delegate.fileInfo(path);
  @override Future<Result<List<FileInfo>, FileError>> listDir(String path) => _delegate.listDir(path);
  @override Future<Result<Uint8List, FileError>> readBinaryFile(String path) => _delegate.readBinaryFile(path);
  @override Future<Result<String, FileError>> readTextFile(String path) => _delegate.readTextFile(path);
  @override Future<Result<List<String>, FileError>> readTextLines(String path, {int? maxLines}) => _delegate.readTextLines(path, maxLines: maxLines);
  @override Future<Result<void, FileError>> remove(String path, {bool recursive = false, bool force = false}) => _delegate.remove(path, recursive: recursive, force: force);
  @override Future<Result<void, FileError>> writeBinaryFile(String path, Uint8List c) => _delegate.writeBinaryFile(path, c);
  @override Future<Result<String, FileError>> joinPath(List<String> parts) => _delegate.joinPath(parts);
  @override Future<Result<ShellExecResult, ExecutionError>> exec(String command, {ShellExecOptions? options}) => _delegate.exec(command, options: options);
}

void main() {
  test('it3 debug', () async {
    final frames = _FrameSink();
    final keys = StreamController<List<int>>();
    final env = MemoryExecutionEnv(cwd: '/work');
    final throwing = _ThrowingWriteEnv(env)..throwOnPath = '/home/u/.fah/config.yaml';
    final io = FakeCliIO();
    const config = '''
provider: copilot
model: gemini-4-argon
models:
  overrides:
    "copilot":
      "gemini-4-argon":
        contextWindow: 204800
''';
    await env.writeFile('/home/u/.fah/config.yaml', config);
    final cli = AgentCli(
      config: AgentCliConfig(
        model: const Model(
          id: 'gemini-4-argon', api: 'copilot', provider: 'copilot',
          baseUrl: 'https://api.githubcopilot.com/',
          contextWindow: 204800, maxTokens: 16384,
        ),
        apiKey: 'x', env: throwing, homeDir: '/home/u', sessionRoot: '/sessions',
        modelsConfig: ModelsConfig.fromYaml((loadYaml(config) as Map)['models']),
        providerKind: 'copilot',
        skillsAccess: SkillsAccess.granted,
        tuiProgramHooks: TuiProgramHooks(
          input: keys.stream, output: frames, width: 80, height: 24),
      ),
      io: io, useTui: true,
      streamFunction: FakeStreamFunction(const []).call,
    );
    final run = cli.run();
    unawaited(run.catchError((Object _) {}));
    await waitForIt(() => frames.text.contains('\x1b[?1049h'));
    print('=== boot done, writes: ${throwing.writes}');
    final submit = cli.tuiSubmitForTest('/model-edit', const []);
    await waitForIt(() => frames.plain.contains('capabilities — copilot/gemini-4-argon'));
    print('=== caps menu open');
    await cli.tuiWizardPickForTest('wizard:capabilities — copilot/gemini-4-argon', 'maxTokens');
    await waitForIt(() => frames.plain.contains('Enter a number manually'));
    print('=== ladder open');
    await cli.tuiWizardPickForTest('wizard:maxTokens in tokens', '65536');
    print('=== picked 65536; writes now: ${throwing.writes}');
    await submit.timeout(const Duration(seconds: 8), onTimeout: () {
      print('=== SUBMIT DID NOT SETTLE');
      throw StateError('submit hang');
    });
    print('=== submit settled; error panel? ${frames.plain.contains('disk full')}');
    keys.add([0x03]); keys.add([0x03]);
    await run.timeout(const Duration(seconds: 5), onTimeout: () {});
  });
}
EOF
